"use client";

import type { ButtonHTMLAttributes } from "react";
import { forwardRef } from "react";
import type { PolymorphicComponent } from "../../system";
import {
  Slot,
  cn,
  disabledInteractiveStyles,
  focusVisibleStyles,
  swirskiAttrs,
} from "../../system";
import { useDialog } from "./DialogContext";
import type { DialogSize, DialogTone, DialogVariant } from "./dialog-types";
import { dialogButtonSizeStyles } from "./dialog-utils";

export type DialogCloseProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  asChild?: boolean;
  /** @deprecated This only sets a data attribute. Omit it for built-in styling, or use className or style to customize. */
  variant?: DialogVariant;
  size?: DialogSize;
  /** @deprecated Omit this prop. The component uses the only supported value by default. */
  tone?: DialogTone;
};

export const DialogClose = forwardRef<HTMLButtonElement, DialogCloseProps>(
  function DialogClose(
    {
      asChild = false,
      className,
      children = "Close",
      variant: variantProp,
      size: sizeProp,
      tone: toneProp,
      disabled,
      onClick,
      ...props
    },
    ref,
  ) {
    const styles = useDialog();
    const variant = variantProp ?? styles.variant ?? "default";
    const size = sizeProp ?? styles.size ?? "md";
    const tone = toneProp ?? styles.tone ?? "default";
    const { setOpen } = styles;
    const isDisabled = disabled || props["aria-disabled"] === true || props["aria-disabled"] === "true";
    const Component = asChild ? Slot : "button";

    return (
      <Component
        ref={ref}
        className={cn(
          "border-[length:var(--sw-border-width)] border-[color:var(--sw-color-ink)] bg-[var(--sw-color-surface)] font-black uppercase shadow-[4px_4px_0_var(--sw-color-shadow)] outline-none sw-motion-shift transition-all duration-[var(--sw-motion-fast,150ms)] hover:translate-x-1 hover:translate-y-1 hover:shadow-none active:translate-x-2 active:translate-y-2 disabled:hover:shadow-[4px_4px_0_var(--sw-color-shadow)]",
          focusVisibleStyles,
          disabledInteractiveStyles,
          dialogButtonSizeStyles[size],
          className,
        )}
        onClick={(event) => {
          if (isDisabled) {
            event.preventDefault();
            return;
          }
          onClick?.(event);

          if (!event.defaultPrevented) {
            setOpen(false);
          }
        }}
        type={asChild ? undefined : "button"}
        {...swirskiAttrs("dialog-close", { size, tone, variant })}
        {...props}
        disabled={asChild ? undefined : disabled}
        aria-disabled={isDisabled || undefined}
        tabIndex={asChild && isDisabled ? -1 : props.tabIndex}
      >
        {children}
      </Component>
    );
  },
) as unknown as PolymorphicComponent<DialogCloseProps, HTMLButtonElement>;

DialogClose.displayName = "DialogClose";

"use client";

import type { HTMLAttributes } from "react";
import { forwardRef, useRef } from "react";
import { createPortal } from "react-dom";
import { cn, composeRefs, swirskiAttrs } from "../../system";
import { OverlayParentContext, useModalOverlay } from "../../system/overlay";
import { usePortalRoot } from "../../hooks/use-portal-root/usePortalRoot";
import { useDialog } from "./DialogContext";
import type { DialogSize, DialogTone, DialogVariant } from "./dialog-types";
import { dialogContentSizeStyles } from "./dialog-utils";

export type DialogContentProps = {
  variant?: DialogVariant;
  size?: DialogSize;
  /** @deprecated Omit this prop. The component uses the only supported value by default. */
  tone?: DialogTone;
} & HTMLAttributes<HTMLDivElement>;

export const DialogContent = forwardRef<HTMLDivElement, DialogContentProps>(
  function DialogContent(
    {
      className,
      children,
      variant: variantProp,
      size: sizeProp,
      tone: toneProp,
      ...props
    },
    ref,
  ) {
    const styles = useDialog();
    const variant = variantProp ?? styles.variant ?? "default";
    const size = sizeProp ?? styles.size ?? "md";
    const tone = toneProp ?? styles.tone ?? "default";
    const { describedById, labelledById, open, setOpen } = styles;
    const portalRoot = usePortalRoot();
    const contentRef = useRef<HTMLDivElement>(null);

    useModalOverlay({
      contentRef,
      onEscape: () => setOpen(false),
      open: open && Boolean(portalRoot),
    });

    if (!open || !portalRoot) {
      return null;
    }

    return createPortal(
      <div className="fixed inset-0 z-50 grid place-items-center bg-black/45 p-4">
        <div
          aria-hidden="true"
          data-swirski-backdrop=""
          className="absolute inset-0"
        />
        <div
          ref={composeRefs(contentRef, ref)}
          className={cn(
            "relative z-10 w-full border-[length:var(--sw-border-width)] border-[color:var(--sw-color-ink)] bg-[var(--sw-color-surface)] text-[var(--sw-color-ink)]",
            dialogContentSizeStyles[size],
            variant === "compact" ? "shadow-[8px_8px_0_var(--sw-color-shadow)]" : "shadow-[12px_12px_0_var(--sw-color-shadow)]",
            className,
          )}
          role="dialog"
          aria-modal="true"
          aria-labelledby={labelledById ?? props["aria-labelledby"]}
          aria-describedby={describedById ?? props["aria-describedby"]}
          tabIndex={-1}
          data-state="open"
          {...swirskiAttrs("dialog-content", { size, tone, variant })}
          {...props}
        >
          <OverlayParentContext.Provider value={contentRef}>
            {children}
          </OverlayParentContext.Provider>
        </div>
      </div>,
      portalRoot,
    );
  },
);

DialogContent.displayName = "DialogContent";

"use client";

import { useControllableState } from "../../hooks/use-controllable-state/useControllableState";
import type { ReactNode } from "react";
import { createContext, useContext, useId, useState } from "react";
import type { DialogSize, DialogTone, DialogVariant } from "./dialog-types";

type DialogContextValue = {
  variant: DialogVariant;
  size: DialogSize;
  tone: DialogTone;
  open: boolean;
  setOpen: (open: boolean) => void;
  titleId: string;
  descriptionId: string;
  labelledById?: string;
  describedById?: string;
  setLabelledById: (id: string | undefined) => void;
  setDescribedById: (id: string | undefined) => void;
};

export const DialogContext = createContext<DialogContextValue | null>(null);

export type DialogProps = {
  children: ReactNode;
  /** Controlled open state. Pair with onOpenChange. */
  open?: boolean;
  /** Initial uncontrolled open state. Defaults to false. */
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  variant?: DialogVariant;
  size?: DialogSize;
  /** @deprecated Omit this prop. The component uses the only supported value by default. */
  tone?: DialogTone;
};

export function useDialogStyles() {
  return useContext(DialogContext);
}

export function useDialog() {
  const context = useContext(DialogContext);

  if (!context) {
    throw new Error("Dialog components must be used inside Dialog.");
  }

  return context;
}

export function Dialog({
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  variant = "default",
  size = "md",
  tone = "default",
}: DialogProps) {
  const titleId = useId();
  const descriptionId = useId();
  const [currentOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const [labelledById, setLabelledById] = useState<string | undefined>();
  const [describedById, setDescribedById] = useState<string | undefined>();

  return (
    <DialogContext.Provider
      value={{
        open: currentOpen, variant, size, tone,
        setOpen,
        titleId,
        descriptionId,
        labelledById,
        describedById,
        setLabelledById,
        setDescribedById,
      }}
    >
      {children}
    </DialogContext.Provider>
  );
}

"use client";

